import React, { useState } from 'react';
import { FileText, Search, Filter, Download, AlertCircle, Info, CheckCircle, XCircle } from 'lucide-react';
import { Badge } from '../../components/shared/Badge';

interface LogEntry {
  id: string;
  timestamp: string;
  level: 'error' | 'warning' | 'info' | 'success';
  source: string;
  message: string;
  user?: string;
  ip?: string;
}

const logs: LogEntry[] = [
  { id: '1', timestamp: '2024-07-20 14:35:22', level: 'error', source: 'Authentication', message: 'Failed login attempt detected', user: 'admin', ip: '192.168.1.105' },
  { id: '2', timestamp: '2024-07-20 14:34:15', level: 'warning', source: 'Firewall', message: 'Port scan detected from external IP', ip: '203.0.113.45' },
  { id: '3', timestamp: '2024-07-20 14:33:08', level: 'info', source: 'System', message: 'Database backup completed successfully', user: 'system' },
  { id: '4', timestamp: '2024-07-20 14:32:00', level: 'success', source: 'Security', message: 'Threat blocked successfully', ip: '10.0.5.23' },
  { id: '5', timestamp: '2024-07-20 14:30:45', level: 'error', source: 'API', message: 'Rate limit exceeded for client', ip: '185.12.55.100' },
  { id: '6', timestamp: '2024-07-20 14:28:30', level: 'warning', source: 'Database', message: 'High query latency detected', user: 'db_monitor' },
  { id: '7', timestamp: '2024-07-20 14:25:12', level: 'info', source: 'Audit', message: 'User permissions updated', user: 'admin' },
  { id: '8', timestamp: '2024-07-20 14:22:55', level: 'error', source: 'Network', message: 'Connection timeout to external service', ip: '172.16.31.98' },
];

export function LogsPage() {
  const [searchQuery, setSearchQuery] = useState('');
  const [filterLevel, setFilterLevel] = useState<string>('all');

  const filteredLogs = logs.filter((log) => {
    const matchesSearch = log.message.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         log.source.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesLevel = filterLevel === 'all' || log.level === filterLevel;
    return matchesSearch && matchesLevel;
  });

  const getLevelIcon = (level: string) => {
    switch (level) {
      case 'error': return <XCircle className="w-4 h-4 text-red-400" />;
      case 'warning': return <AlertCircle className="w-4 h-4 text-yellow-400" />;
      case 'success': return <CheckCircle className="w-4 h-4 text-emerald-400" />;
      default: return <Info className="w-4 h-4 text-blue-400" />;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-100">Log Analysis</h1>
          <p className="text-sm text-slate-400 mt-1">Monitor and analyze system logs</p>
        </div>
        <button className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-slate-300 transition-all">
          <Download className="w-4 h-4" />
          Export Logs
        </button>
      </div>

      <div className="flex flex-col sm:flex-row gap-4">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
          <input
            type="text"
            placeholder="Search logs..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-white/5 border border-white/10 rounded-lg text-slate-200 placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-cyan-400/50"
          />
        </div>
        <div className="flex items-center gap-2">
          <Filter className="w-4 h-4 text-slate-400" />
          <select
            value={filterLevel}
            onChange={(e) => setFilterLevel(e.target.value)}
            className="px-4 py-2.5 bg-white/5 border border-white/10 rounded-lg text-slate-200 focus:outline-none focus:ring-2 focus:ring-cyan-400/50"
          >
            <option value="all">All Levels</option>
            <option value="error">Error</option>
            <option value="warning">Warning</option>
            <option value="info">Info</option>
            <option value="success">Success</option>
          </select>
        </div>
      </div>

      <div className="bg-[#0F1729]/50 backdrop-blur-sm border border-white/10 rounded-xl overflow-hidden">
        <div className="p-4 font-mono text-xs space-y-1">
          {filteredLogs.map((log) => (
            <div
              key={log.id}
              className="flex items-start gap-3 p-3 hover:bg-white/5 rounded-lg transition-colors cursor-pointer"
            >
              <div className="flex items-center gap-2 shrink-0 w-40">
                <span className="text-slate-500">{log.timestamp}</span>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                {getLevelIcon(log.level)}
                <Badge variant={log.level === 'error' ? 'critical' : log.level === 'warning' ? 'warning' : log.level === 'success' ? 'success' : 'info'}>
                  {log.level}
                </Badge>
              </div>
              <div className="flex items-center gap-2 shrink-0 w-32">
                <span className="text-cyan-400">[{log.source}]</span>
              </div>
              <div className="flex-1">
                <span className="text-slate-300">{log.message}</span>
              </div>
              {(log.user || log.ip) && (
                <div className="shrink-0 text-slate-500">
                  {log.user && <span>user:{log.user}</span>}
                  {log.ip && <span className="ml-2">ip:{log.ip}</span>}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
